#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Tri Instagram — lanceur local.

Un seul fichier, sans dépendance : il sert la page à votre navigateur et
lui donne accès aux archives Instagram trouvées sur votre ordinateur, sans
passer par la boîte de sélection de fichiers du bureau.

Lancer :   python3 lanceur.py
Arrêter :  Ctrl+C

Options :  --port N        port fixe (sinon un port libre est choisi)
           --no-browser    ne pas ouvrir le navigateur
           <dossier|zip>   dossiers ou archives supplémentaires à proposer
"""
import base64
import http.server
import os
import socketserver
import sys
import threading
import urllib.parse
import webbrowser
from html import escape
from pathlib import Path

HTML_INCORPORE = ''  # rempli par construire.py


def page_html():
    """La page de l'application : le fichier voisin s'il existe, sinon la copie incorporée."""
    voisin = Path(__file__).resolve().parent / 'index.html'
    if voisin.is_file():
        return voisin.read_bytes()
    if HTML_INCORPORE:
        return base64.b64decode(HTML_INCORPORE)
    return b'<!doctype html><meta charset="utf-8"><p>index.html introuvable et aucune copie incorpor\xc3\xa9e.</p>'


def dossiers(extra):
    home = Path.home()
    cands = [Path.cwd(), Path(__file__).resolve().parent,
             home / 'Téléchargements', home / 'Downloads', home / 'Bureau', home / 'Desktop', home]
    out = []
    for d in extra + cands:
        try:
            d = Path(d).expanduser().resolve()
        except Exception:
            continue
        if d.is_dir() and d not in out:
            out.append(d)
    return out


def archives(extra_dirs, extra_files):
    trouvees = {}
    for f in extra_files:
        p = Path(f).expanduser()
        if p.is_file():
            trouvees.setdefault(p.name, p.resolve())
    for d in dossiers(extra_dirs):
        try:
            for p in sorted(d.glob('*.zip')):
                if p.is_file():
                    trouvees.setdefault(p.name, p.resolve())
        except Exception:
            pass
    return trouvees


class Serveur(socketserver.ThreadingMixIn, http.server.HTTPServer):
    daemon_threads = True
    allow_reuse_address = True


def faire_handler(extra_dirs, extra_files):
    class H(http.server.BaseHTTPRequestHandler):
        def log_message(self, fmt, *args):
            sys.stdout.write('  ' + (fmt % args) + '\n')

        def envoyer(self, code, corps, ctype='text/html; charset=utf-8'):
            self.send_response(code)
            self.send_header('Content-Type', ctype)
            self.send_header('Content-Length', str(len(corps)))
            self.send_header('Cache-Control', 'no-store')
            self.end_headers()
            if self.command != 'HEAD':
                self.wfile.write(corps)

        def do_HEAD(self):
            self.do_GET()

        def do_GET(self):
            chemin = urllib.parse.unquote(self.path.split('?', 1)[0])
            if chemin in ('/', '/index.html'):
                arcs = archives(extra_dirs, extra_files)
                lignes = ''.join('<li><a href="%s">%s</a> <small>(%s)</small></li>' % (
                    urllib.parse.quote(n), escape(n), taille(p)) for n, p in arcs.items())
                corps = ('<!doctype html><html lang="fr"><meta charset="utf-8"><title>Tri Instagram</title>'
                         '<body style="font:15px system-ui;background:#0b0b0d;color:#f2f2f4;padding:24px">'
                         '<p><a href="/app" style="color:#f0b429;font-size:20px">Ouvrir Tri Instagram</a></p>'
                         '<p>Archives disponibles :</p><ul>' + (lignes or '<li>aucune archive .zip trouvée</li>') +
                         '</ul></body></html>').encode('utf-8')
                return self.envoyer(200, corps)
            if chemin == '/app':
                return self.envoyer(200, page_html())
            nom = chemin.lstrip('/')
            arcs = archives(extra_dirs, extra_files)
            if nom in arcs:
                p = arcs[nom]
                total = p.stat().st_size
                self.send_response(200)
                self.send_header('Content-Type', 'application/zip')
                self.send_header('Content-Length', str(total))
                self.send_header('Cache-Control', 'no-store')
                self.end_headers()
                if self.command == 'HEAD':
                    return
                with open(p, 'rb') as f:
                    while True:
                        bloc = f.read(1024 * 1024)
                        if not bloc:
                            break
                        try:
                            self.wfile.write(bloc)
                        except (BrokenPipeError, ConnectionResetError):
                            return
                return
            self.envoyer(404, b'<!doctype html><meta charset="utf-8"><p>Introuvable.</p>')
    return H


def taille(p):
    n = p.stat().st_size
    for u in ('o', 'Ko', 'Mo', 'Go'):
        if n < 1024 or u == 'Go':
            return ('%d %s' % (n, u)) if u == 'o' else ('%.1f %s' % (n, u))
        n /= 1024.0


def main(argv):
    port = 0
    ouvrir = True
    extra_dirs, extra_files = [], []
    it = iter(argv)
    for a in it:
        if a == '--port':
            port = int(next(it, '0'))
        elif a == '--no-browser':
            ouvrir = False
        elif a in ('-h', '--help'):
            print(__doc__)
            return 0
        else:
            p = Path(a).expanduser()
            (extra_dirs if p.is_dir() else extra_files).append(p)

    try:
        srv = Serveur(('127.0.0.1', port), faire_handler(extra_dirs, extra_files))
    except OSError as e:
        if port:
            print('Le port %d est occupé (%s). Relancez sans --port : un port libre sera choisi.' % (port, e))
            return 1
        raise
    port = srv.server_address[1]
    url = 'http://127.0.0.1:%d/app' % port

    arcs = archives(extra_dirs, extra_files)
    print('')
    print('  Tri Instagram est prêt.')
    print('  Adresse :  %s' % url)
    print('  Archives trouvées : %d' % len(arcs))
    for n, p in list(arcs.items())[:10]:
        print('     - %s  (%s)' % (n, taille(p)))
    if not arcs:
        print('     (aucune : placez l\'archive Instagram dans Téléchargements, ou passez son chemin en argument)')
    print('  Arrêt : Ctrl+C')
    print('')
    sys.stdout.flush()

    if ouvrir:
        def ouvre():
            try:
                webbrowser.open(url, new=2)
            except Exception:
                pass
        threading.Timer(0.4, ouvre).start()
    try:
        srv.serve_forever()
    except KeyboardInterrupt:
        print('\n  Arrêté.')
    finally:
        srv.server_close()
    return 0


if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
